#include <bits/stdc++.h>
using namespace std;using E=pair<int,int>;using S=vector<E>;const int n=9,m=36;
bool conn(const S&a,uint64_t mask){uint16_t inf[9]={1,2,4,8,16,32,64,128,256};for(int i=0;i<m;i++)if((mask>>i)&1){auto [u,v]=a[i];inf[u]|=inf[v];inf[v]=inf[u];}for(int i=0;i<n;i++)if(inf[i]!=511)return false;return true;}
bool pivot(const S&a){uint16_t pre[9],fut[9],suff[36];for(int i=0;i<n;i++)pre[i]=fut[i]=1<<i;for(int i=m-1;i>=0;i--){auto [u,v]=a[i];suff[i]=fut[u]|fut[v];fut[u]=fut[v]=suff[i];}for(int i=0;i<m;i++){auto [u,v]=a[i];if((pre[u]|pre[v])==511&&suff[i]==511)return true;pre[u]|=pre[v];pre[v]=pre[u];}return false;}
uint64_t forced(const S&a){uint64_t full=(1ull<<m)-1, mask=0;for(int i=0;i<m;i++)if(!conn(a,full^(1ull<<i)))mask|=1ull<<i;return mask;}
int main(int argc,char**argv){int trials=argc>1?atoi(argv[1]):200000;S base;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)base.emplace_back(i,j);mt19937 rng(232347);int cnt=0,best=0,numHigh=0;S witness;uint64_t bestmask=0;for(int k=0;k<trials;k++){S a=base;int swaps=1+rng()%12;for(int j=0;j<swaps;j++){int x=rng()%m,y=rng()%m;swap(a[x],a[y]);}if(pivot(a))continue;cnt++;uint64_t fm=forced(a);int f=__builtin_popcountll(fm);if(f>best){best=f;witness=a;bestmask=fm;cerr<<"best "<<best<<" trial "<<k<<" nonpivot "<<cnt<<"\n";}if(f>=13)numHigh++;if(f>=14&&!conn(a,fm)){cerr<<"LOWER-BOUND PROOF CANDIDATE "<<f<<"\n";witness=a;bestmask=fm;break;}}
cout<<"trials "<<trials<<" no_pivot "<<cnt<<" best_forced "<<best<<" high>=13 "<<numHigh<<"\n";if(!witness.empty()){cout<<"forced_mask "<<bestmask<<"\n";for(auto [u,v]:witness)cout<<u<<" "<<v<<"\n";}}
